import React, { useEffect, useState } from 'react'
import EntitiesTable from './EntitiesTable'

import useApi from '../../hooks/useApi'
import { useNavigate, useParams } from 'react-router-dom';
import EntitiesFormModalAdmin from './EntitiesFormModalAdmin';
import genericsApi from '../../api/drugs/genericsApi';
import entitiesApi from '../../api/entitiesApi';
import { getLoggedInUser } from '../../helpers/authUtils';
import EntitiesFormModal from './EntitiesFormModal';
import { Loading } from '../../components';

const columns = [

    { name: "Title", uid: "title" },
    { name: "Type", uid: "entity_type" },
    { name: "Country", uid: "country_title" },
    { name: "County", uid: "county_title" },
    { name: "City", uid: "town" },
    { name: "Road", uid: "road" },
    { name: "Building", uid: "building" },
    { name: "Actions", uid: "actions" },
];


function WholesaleEntitiesList() {
    const [openEntityFormModalAdmin, setopenEntityFormModalAdmin] = useState(false)
    const [openEntityFormModal, setopenEntityFormModal] = useState(false)
    const navigate = useNavigate()
    const [entity, setEntity] = useState()
    const [entities, setEntities] = useState([])
    const [data, setdata] = useState([])
    const [updated, setUpdated] = useState(false)
    const [modalTitle, setmodalTitle] = useState("")
    const entitiesActionsApi = useApi(entitiesApi.entitiesAction)

    const [user, setUser] = useState()



    useEffect(() => {
      setUser(getLoggedInUser());
    }, []);

    useEffect(() => {
      console.log("user", user);
    }, [user]);

    const getEntities = async (action) => {
      setEntities([]);
      await entitiesActionsApi.request({
        action: action,
      });
    };

    useEffect(() => {
      getEntities("GetWholesaleEntities");
    }, []);

    const handleEditAction = (item) => {
      if (user && user.is_staff === "true") {
        setopenEntityFormModalAdmin(true);
      }
      setUpdated(false);

      setEntity(item);
      setmodalTitle(`${item.title}`);
    };

    const handleAddAction = () => {
      if (user && user.is_staff === "true") {
        setopenEntityFormModalAdmin(true);
      } else {
        setopenEntityFormModal(true);
      }
      setUpdated(false);

      setmodalTitle("Add new entity");
      setEntity(null);
    };
    const handleDetailsAction = (item) => {
      navigate(`/entities/details/${item.id}`, {
        state: {
          item: item,
        },
      });
    };
    const handleDeleteAction = (item) => {
      navigate(`/entities/delete/${item.id}`);
    };

    useEffect(() => {
      if (entitiesActionsApi.data && entitiesActionsApi.data.length) {
        setEntities(entitiesActionsApi.data);
      }

      console.log("entitiesActionsApi.data", entitiesActionsApi.data);
    }, [entitiesActionsApi.data]);

    // useEffect(() => {
    //     getEntities()
    // }, [openEntityFormModal])

    //Filtering data
    useEffect(() => {
      setdata(entities);
    }, [entities]);

    const handleFilter = (e) => {
      console.log("eeeee", e);
      const search_param = e;

      if (search_param && search_param !== "") {
        setdata(
          entities.filter((x) => x.title.toLowerCase().includes(search_param))
        );
      } else {
        setdata(entities);
      }
    };

    return (
      <div>
        {openEntityFormModal && (
          <EntitiesFormModal
            openEditModal={openEntityFormModal}
            setopenEditModal={setopenEntityFormModal}
            item={entity}
            updated={updated}
            setUpdated={setUpdated}
            modalTitle={modalTitle}
          />
        )}
        {openEntityFormModalAdmin && (
          <EntitiesFormModalAdmin
            ismodalOpen={openEntityFormModalAdmin}
            setisModalOpen={setopenEntityFormModalAdmin}
            entity={entity}
            updated={updated}
            setUpdated={setUpdated}
            modalTitle={modalTitle}
          />
        )}
        {entitiesActionsApi.loading ? (
          <Loading loading={entitiesActionsApi.loading} />
        ) : (
          <EntitiesTable
            data={data}
            columns={columns}
            editAction={handleEditAction}
            detailsAction={handleDetailsAction}
            deleteAction={handleDeleteAction}
            addAction={handleAddAction}
            handleFilter={handleFilter}
          />
        )}
      </div>
    );
}

export default WholesaleEntitiesList